def below_zero(operations):
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    """
    Returns the index (1‑based) of the topmost carpet covering a point.
    If no carpet covers the point, returns -1.
    """
    # Basic validation
    try:
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if not isinstance(carpets, list) or len(carpets) != n:
            raise ValueError("carpets must be a list of length n")
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError("point must be a tuple of length 2")
    except Exception as e:
        # For any invalid input we simply return -1 as no carpet can be chosen
        return -1

    x, y = point
    # Iterate from topmost to bottommost
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        # Ensure carpet specs are integers
        if not all(isinstance(v, int) for v in (a, b, g, k)):
            continue
        # Check if point lies inside the rectangle (inclusive boundaries)
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1  # 1‑based indexing

    return -1

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all 26 letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    enc_to_orig = {}
    orig_to_enc = {}

    for e, o in zip(encoded, original):
        # Check for forward mapping contradiction
        if e in enc_to_orig:
            if enc_to_orig[e] != o:
                return "Failed"
        else:
            enc_to_orig[e] = o

        # Check for reverse mapping contradiction
        if o in orig_to_enc:
            if orig_to_enc[o] != e:
                return "Failed"
        else:
            orig_to_enc[o] = e

    # Ensure full alphabet mapping (26 unique encoded letters)
    if len(enc_to_orig) < 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in enc_to_orig:
            return "Failed"
        decoded_chars.append(enc_to_orig[ch])

    return "".join(decoded_chars)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.

    Args:
        inorder (str): The inorder traversal of the binary tree.
        postorder (str): The postorder traversal of the binary tree.

    Returns:
        str: The preorder traversal of the binary tree.

    Raises:
        ValueError: If the input strings are of different lengths,
                    contain mismatched characters, or the traversals do not
                    correspond to a valid binary tree.
    """
    if not inorder and not postorder:
        return ""
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must be of the same length.")

    try:
        index_map = {ch: idx for idx, ch in enumerate(inorder)}
    except Exception as exc:
        raise ValueError("Failed to create index mapping from inorder string.") from exc

    def build(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end or post_start > post_end:
            return ""

        root = postorder[post_end]
        if root not in index_map:
            raise ValueError(f"Character '{root}' from postorder not found in inorder.")

        in_root_pos = index_map[root]
        if not (in_start <= in_root_pos <= in_end):
            raise ValueError(f"Invalid tree structure: root '{root}' position out of bounds.")

        left_len = in_root_pos - in_start
        right_len = in_end - in_root_pos

        left_pre = build(in_start, in_root_pos - 1, post_start, post_start + left_len - 1)
        right_pre = build(in_root_pos + 1, in_end, post_start + left_len, post_end - 1)

        return root + left_pre + right_pre

    try:
        return build(0, len(inorder) - 1, 0, len(postorder) - 1)
    except KeyError as exc:
        raise ValueError("Inorder and postorder sequences do not represent the same set of nodes.") from exc
    except RecursionError as exc:
        raise ValueError("Recursion depth exceeded; possible invalid input.") from exc

